import React, { useEffect, useState } from "react";
import TopBar from "./components/TopBar";
import SearchDropdown from "./components/SearchDropdown";
import UpdateFeed from "./components/UpdateFeed";
import UpdatesChart from "./components/Charts/UpdatesChart";
import ChatBox from "./components/ChatBox";
import "App.css"; // or your actual CSS path

function App() {
  const [selectedComponents, setSelectedComponents] = useState([]);
  const [chartData, setChartData] = useState({});

  useEffect(() => {
    // placeholder for future data fetching
  }, [selectedComponents]);

  return (
    <div className="dashboard dark-theme">
      <TopBar componentCount={13617} versionCount={56260} redditCount={17391} pageCount={1000} />
      <SearchDropdown onChange={setSelectedComponents} />
      <div className="main-content" style={{ display: "flex", gap: "1rem" }}>
        <div className="left-column" style={{ flex: 1 }}>
          <UpdateFeed />
        </div>
        <div className="center-column" style={{ flex: 1 }}>
          <UpdatesChart data={chartData} />
        </div>
        <div className="right-column" style={{ flex: 1 }}>
          <ChatBox />
        </div>
      </div>
    </div>
  );
}

export default App;
